ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"query": {
    "aggregate": p('mongo-db-sapi.collections.facturacion'),
    "pipeline": [
      {
        // Envolvemos el resultado en un $match para que Mongo filtre
        "\$match": {
        	"Cuenta_Facturacion": vars.objectServicio_Tramite.Id_Cuenta_Facturacion
        }
      }
    ],
    "cursor": {}
  }
}

%dw 2.0
output application/json

var TESR = vars.requestOrder.through.throughType
var fecha_corte = vars.responseMongo.result[0].Fecha_Corte_Facturacion

fun pad2(n: Number): String = if (n < 10) "0" ++ (n as String) else (n as String)

fun crearFecha(anno: Number, mes: Number, dia: Number): Date =
	((anno as String) ++ "-" ++ pad2(mes) ++ "-" ++ pad2(dia)) as Date {format: "yyyy-MM-dd"}

fun primerDiaMes(fecha: Date): Date = crearFecha(fecha.year, fecha.month, 1)

fun ultimoDiaMes(fecha: Date): Date = (primerDiaMes(fecha) + |P1M|) - |P1D|

var UMBRAL_DIAS = 3

fun fechaEjecucionCancelacionVoluntaria(fechaCorteFacturacion: Number): Date = do {
	var hoy = now() as Date
	var intDiaCorte = fechaCorteFacturacion default 0
	var corteEsFinDeMes = (intDiaCorte == 0) or (intDiaCorte > 31)
	---
	if (corteEsFinDeMes)
		ultimoDiaMes(hoy)
	else do {
		var fechaCorteMesActual = crearFecha(hoy.year, hoy.month, intDiaCorte)
		var diasParaCorte = (fechaCorteMesActual - hoy) as Number {unit: "days"}
		---
		if (diasParaCorte >= UMBRAL_DIAS)
			fechaCorteMesActual
		else
			fechaCorteMesActual + |P1M|
	}
}

fun generarFechaEjecucionPorCiclo(tramite: String, fechaCorteFacturacion: Number): Date | Null =
	tramite match {
		case t if (t == TESR) -> fechaEjecucionCancelacionVoluntaria(fechaCorteFacturacion)
		else -> null
	}

var fecha = generarFechaEjecucionPorCiclo(
	TESR default "TESR",
	fecha_corte default "0"
)
---
{  
	objectCuentaFacturacion: vars.responseMongo.result[0],
	fechaEjecucion: if (fecha != null)
		{
			"\$date": (fecha as String {format: "yyyy-MM-dd"}) ++ "T00:00:00.000Z"
		}
	else
		null
}
